import numpy as np

# Define the equation
def find_x(e, o):
    return (9 - 0.6 * o) / (0.03 * e)

# Try some values for e and o
for e in np.linspace(1, 100, 1000):
    for o in np.linspace(1, 100, 1000):
        x = find_x(e, o)
        if np.isclose(x, round(x)):
            print(f"Found x = {int(round(x))} for e = {e:.2f}, o = {o:.2f}")
            break
